// TP : remplace le RSS par les 3 alertes figées de /data/certfr.
// L'alerte piégée (alerte-piegee*.xml, exercice B4) est EXCLUE par défaut : passez INCLURE_PIEGEE à true
// (ou lancez le workflow depuis le déclencheur « Exécution manuelle (B4 injection) ») pour l'inclure.
const fs = require('fs');
const dir = '/data/certfr/';
const INCLURE_PIEGEE = false;
const viaB4 = $prevNode && $prevNode.name === 'Exécution manuelle (B4 injection)';
const inclurePiegee = INCLURE_PIEGEE || viaB4;
const items = [];
for (const f of fs.readdirSync(dir).filter(n => n.endsWith('.xml') || n.endsWith('.txt')).sort()) {
  if (f.startsWith('alerte-piegee') && !inclurePiegee) continue;
  const content = fs.readFileSync(dir + f, 'utf8');
  items.push({ json: { title: f, link: 'file://' + dir + f, content, isoDate: new Date().toISOString() } });
}
return items;

// Ne traite que les alertes jamais vues (mémoire persistante du workflow).
// Attention : $getWorkflowStaticData n'est PERSISTÉ que pour les exécutions déclenchées (Cron) d'un workflow actif ;
// en exécution manuelle (bouton « Test workflow »), la mémoire repart vide à chaque lancement — pratique pour le TP.
const seen = $getWorkflowStaticData('global');
seen.links = seen.links || [];
const out = [];
for (const item of $input.all()) {
  const key = item.json.link || item.json.title;
  if (!seen.links.includes(key)) { seen.links.push(key); out.push(item); }
}
if (seen.links.length > 500) seen.links = seen.links.slice(-500);
return out;

// Construit le prompt à partir du gabarit versionné dans /prompts.
const fs = require('fs');
const template = fs.readFileSync('/prompts/extraction-certfr.md', 'utf8');
return $input.all().map(item => {
  const text = (item.json.content || item.json.contentSnippet || item.json.title || '').toString().slice(0, 12000);
  return { json: { ...item.json, source_text: text, prompt: template.replace('{{TEXTE}}', text) } };
});

// Validation : schéma + littéralité (chaque IoC/CVE doit apparaître dans le texte source).
// C'est ICI que se joue la défense contre l'hallucination et une partie de celle contre l'injection.
// Nœud en mode « Run Once for All Items » : on retrouve l'item source par son index avec itemMatching(i),
// jamais avec .item (qui ne désigne que l'item courant en mode « Run Once for Each Item »).
const out = [];
for (const [i, item] of $input.all().entries()) {
  const src = $('Préparer le prompt').itemMatching(i).json;
  const text = (src.source_text || '').toLowerCase();
  let parsed;
  try { parsed = JSON.parse(item.json.response); } catch (e) {
    out.push({ json: { rejected: true, reason: 'JSON invalide', raw: item.json.response, title: src.title } });
    continue;
  }
  const allowedTlp = ['clear', 'green', 'amber', 'amber+strict', 'red'];
  const cves = (parsed.cve || []).filter(c => /^CVE-\d{4}-\d{4,}$/i.test(c) && text.includes(c.toLowerCase()));
  const iocs = (parsed.ioc || []).filter(i => i && i.value && text.includes(String(i.value).toLowerCase()));
  const dropped = { cve: (parsed.cve || []).length - cves.length, ioc: (parsed.ioc || []).length - iocs.length };
  const tlp = allowedTlp.includes(String(parsed.tlp || '').toLowerCase()) ? String(parsed.tlp).toLowerCase() : 'amber';
  const attack = (parsed.attack_tactics || []).filter(t => /^TA\d{4}$/.test(t));
  // Techniques (T1234 / T1234.001) : objets {id, name} ou simples identifiants, selon le prompt.
  const techniques = (parsed.attack_techniques || []).map(t => (typeof t === 'string' ? { id: t } : t))
    .filter(t => t && /^T\d{4}(\.\d{3})?$/.test(String(t.id || '')));
  out.push({ json: {
    rejected: false, title: src.title, link: src.link,
    summary: String(parsed.summary || '').slice(0, 1000),
    products: (parsed.products || []).slice(0, 20),
    cve: cves, ioc: iocs, attack_tactics: attack, attack_techniques: techniques, tlp,
    dropped, latency_ms: Math.round((item.json.total_duration || 0) / 1e6),
    model: item.json.model
  } });
}
return out;

// Construit l'événement MISP. Le tag workflow:ia-non-verifie est obligatoire.
// Catégories MISP : hash -> Payload delivery ; CVE -> External analysis ; IP/domaine/URL -> Network activity.
const TYPE_MAP = { ip: 'ip-dst', domain: 'domain', hostname: 'hostname', url: 'url', md5: 'md5', sha1: 'sha1', sha256: 'sha256', email: 'email-src' };
const CATEGORY = { md5: 'Payload delivery', sha1: 'Payload delivery', sha256: 'Payload delivery', 'email-src': 'Payload delivery',
                   vulnerability: 'External analysis', 'ip-dst': 'Network activity', domain: 'Network activity',
                   hostname: 'Network activity', url: 'Network activity' };
// Tags ATT&CK : galaxie MISP seulement si on a un nom ("Nom - T1234") ; sinon tag simple attack:T1234 ;
// les tactiques (TAxxxx) n'ont pas de galaxie attack-pattern : tag simple attack-tactic:TAxxxx.
function attackTag(id, name) {
  id = String(id).toUpperCase();
  if (id.startsWith('TA')) return 'attack-tactic:' + id;
  if (name) return 'misp-galaxy:mitre-attack-pattern="' + name + ' - ' + id + '"';
  return 'attack:' + id;
}
return $input.all().map(item => {
  const j = item.json;
  const attrs = [];
  for (const c of j.cve) attrs.push({ type: 'vulnerability', category: CATEGORY.vulnerability, value: c, to_ids: false });
  for (const i of j.ioc) {
    const t = TYPE_MAP[String(i.type || '').toLowerCase()];
    if (t) attrs.push({ type: t, category: CATEGORY[t] || 'Network activity', value: i.value, to_ids: false, comment: 'extrait par LLM - a verifier' });
  }
  for (const p of j.products) attrs.push({ type: 'text', category: 'Other', value: 'Produit: ' + p, to_ids: false });
  attrs.push({ type: 'link', category: 'External analysis', value: j.link || 'n/a', to_ids: false });
  attrs.push({ type: 'comment', category: 'Other', value: j.summary, to_ids: false });
  const tags = [ { name: 'tlp:' + j.tlp }, { name: 'workflow:ia-non-verifie' }, { name: 'source:cert-fr' } ];
  for (const t of (j.attack_tactics || [])) tags.push({ name: attackTag(t) });
  for (const t of (j.attack_techniques || [])) tags.push({ name: attackTag(t.id, t.name) });
  return { json: { Event: { info: '[CERT-FR] ' + j.title, distribution: 0, threat_level_id: 2, analysis: 0, Attribute: attrs, Tag: tags } , meta: j } };
});

// Journal des rejets et des mesures, pour le livrable eval-extraction.md
// Mode « Run Once for All Items » : on itère sur $input.all() (et non sur $json, qui ne vaut que pour le premier item).
const fs = require('fs');
for (const item of $input.all()) {
  const line = JSON.stringify({ ts: new Date().toISOString(), ...item.json }) + '\n';
  fs.appendFileSync('/out/certfr-rejets.jsonl', line);
}
return $input.all();

// Mesures par alerte (latence, nb CVE/IoC retenus et écartés, id MISP) pour le livrable eval-extraction.md.
const fs = require('fs');
for (const [i, item] of $input.all().entries()) {
  const m = $('Construire l\'événement MISP').itemMatching(i).json.meta;
  fs.appendFileSync('/out/certfr-mesures.jsonl', JSON.stringify({ ts: new Date().toISOString(), title: m.title, model: m.model, latency_ms: m.latency_ms, n_cve: m.cve.length, n_ioc: m.ioc.length, dropped: m.dropped, tlp: m.tlp, misp_event_id: item.json.Event ? item.json.Event.id : null }) + '\n');
}
return $input.all();
